def collect_atoms(node, out):
    stack = [node]
    while stack:
        cur = stack.pop()
        tag = cur[0]
        if tag == 'and' or tag == 'or':
            stack.extend(cur[1])
        elif tag == 'not':
            stack.append(cur[1])
        elif tag == 'const':
            pass
        else:
            if cur not in out:
                out[cur] = None


